sidebar.template:
{% set days = ['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'] %}<li>{% if now().hour < 5 %}Gute Nacht,{% elif now().hour < 12 %}Guten Morgen,{% elif now().hour < 18 %}Guten Tag,{% else %}Guten Abend,{% endif %} heute ist {{ days[now().weekday()] }}, der {{ now().strftime('%d.%m.%Y') }}</li>
{% if 'Müll' in states('calendar.hausordnung') %}<li>Heute Müll rausstellen!</li>{% endif %}
{% if 'Hausordnung' in states('calendar.hausordnung') %}<li>Heute Hausordnung</li>{% endif %}
{% if is_state('person.carsten_martens', 'home') %}<li>Carsten ist zuhause 🏠</li>{% elif is_state('person.carsten_martens', 'not_home') %}<li>Carsten ist unterwegs 🚗</li>{% else %}<li>Carsten: {{ states('person.carsten_martens') }}</li>{% endif %}
{% if is_state('person.elke_martens', 'home') %}<li>Elke ist zuhause 🏠</li>{% elif is_state('person.elke_martens', 'not_home') %}<li>Elke ist unterwegs 🚗</li>{% else %}<li>Elke: {{ states('person.elke_martens') }}</li>{% endif %}
